}

::deep .priority-medium {
    background: #fff3cd;
    color: #664d03;
}

::deep .priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

::deep .task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

::deep .task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

::deep .btn-move {
    padding: 0.25rem 0.5rem;
    font-size: 0.75rem;
    border: 1px solid #dee2e6;
